-- HISTORICAL SOURCE ONLY. Current installation: UpgradeModernWorkflows.sql.
-- This file is retained for historical reference and is not part of application startup.
-- =====================================================================
--  Warehouse Inventory (PK / RM / FG) - schema + data + views
--  สร้างจากไฟล์: _WH__Inventory_PK.xlsx, _WH__Inventory_RM.xlsx, _WH__Inventory_FG.xlsx
--  Dialect: SQLite 3.25+ (ตัวอย่าง: sqlite3 warehouse.db < warehouse_inventory.sql)
--  ถ้าใช้ MySQL/PostgreSQL: ตารางและ INSERT ใช้ได้ทันที ต้องแก้เฉพาะฟังก์ชันวันที่ใน views
--  (date(x,'-90 day') ) และ DROP VIEW/TABLE ด้านล่าง
--
--  ลำดับงาน
--   1) ทำความสะอาดข้อมูล  -> ทำแล้วตอนนำเข้า, ผลดูได้ที่ตาราง data_issue_log
--   2) Product_Group       -> ตาราง product_group + item_master.group_id
--   3) BOM                 -> ตาราง bom (สูตร RM + แพกเกจ)
--   4) Min/Safe + Discontinued -> param_lead_time, item_master.status, view v_reorder_suggestion / v_inventory
--   5) Lot FG              -> fg_lot, movement.lot_id, views v_lot_stock / v_lot_fefo / v_lot_expiry_alerts / v_fg_lot_reconcile
-- =====================================================================
PRAGMA foreign_keys = OFF;
DROP TRIGGER IF EXISTS trg_mov_lot_item;
DROP TRIGGER IF EXISTS trg_mov_lot_overdraw;
DROP VIEW  IF EXISTS v_lot_expiry_alerts;
DROP VIEW  IF EXISTS v_lot_fefo;
DROP VIEW  IF EXISTS v_fg_lot_reconcile;
DROP VIEW  IF EXISTS v_lot_stock;
DROP VIEW  IF EXISTS v_discontinue_candidates;
DROP VIEW  IF EXISTS v_alerts;
DROP VIEW  IF EXISTS v_group_summary;
DROP VIEW  IF EXISTS v_formula_capacity;
DROP VIEW  IF EXISTS v_bom_unmatched;
DROP VIEW  IF EXISTS v_inventory;
DROP VIEW  IF EXISTS v_reorder_suggestion;
DROP VIEW  IF EXISTS v_usage;
DROP VIEW  IF EXISTS v_stock;
DROP TABLE IF EXISTS data_issue_log;
DROP TABLE IF EXISTS bom;
DROP TABLE IF EXISTS movement;
DROP TABLE IF EXISTS fg_lot;
DROP TABLE IF EXISTS item_master;
DROP TABLE IF EXISTS param_lead_time;
DROP TABLE IF EXISTS product_group;
PRAGMA foreign_keys = ON;

-- ============ 1) SCHEMA ============
CREATE TABLE product_group (
  group_id    VARCHAR(10)  PRIMARY KEY,
  group_name  VARCHAR(200) NOT NULL,
  brand       VARCHAR(100),
  category    VARCHAR(50),                 -- Skin Care / Laundry / Sun Care / Hair Care / Herbal / Unassigned
  status      VARCHAR(12)  NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISCONTINUED'))
);

-- Lead time ใช้คำนวณ Min/Safe อัตโนมัติ (ค่าเริ่มต้นเป็นสมมติฐาน ควรปรับตามจริง)
CREATE TABLE param_lead_time (
  item_type      VARCHAR(2) PRIMARY KEY CHECK (item_type IN ('PK','RM','FG')),
  lead_time_days INTEGER NOT NULL,
  safety_days    INTEGER NOT NULL,
  note           VARCHAR(300)
);

CREATE TABLE item_master (
  item_code     VARCHAR(30)  PRIMARY KEY,
  alt_code      VARCHAR(30),               -- รหัสไทย/จีน (เช่น RSL0001, PS0340)
  item_name     VARCHAR(300) NOT NULL,
  item_type     VARCHAR(2)   NOT NULL CHECK (item_type IN ('PK','RM','FG')),
  group_id      VARCHAR(10)  REFERENCES product_group(group_id),
  unit          VARCHAR(20),               -- ชิ้น / ซอง / kg ...
  origin        VARCHAR(2),                -- TH / CN (เฉพาะ RM)
  buyer         VARCHAR(50),               -- เฉพาะ FG
  supplier      VARCHAR(100),              -- เฉพาะ RM (จากชีต Sheet9)
  unit_cost     DECIMAL(14,4),             -- ต้นทุน/หน่วย (ถ้ามีในต้นฉบับ)
  units_per_box INTEGER,                   -- เฉพาะ FG
  shelf_life_months INTEGER,               -- เฉพาะ FG: อายุสินค้า (เดือน) ใช้คำนวณวันหมดอายุของ Lot ถ้าไม่ได้ระบุ exp_date (ยังไม่มีในต้นฉบับ ต้องกรอก)
  min_stock     DECIMAL(14,3),             -- ตั้งเอง (NULL = ใช้ค่าแนะนำจาก v_reorder_suggestion)
  safe_stock    DECIMAL(14,3),
  status        VARCHAR(12)  NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISCONTINUED')),
  needs_review  INTEGER      NOT NULL DEFAULT 0   -- 1 = สร้างชั่วคราวจาก Movement ต้องตรวจสอบ
);
CREATE INDEX ix_item_group ON item_master(group_id);
CREATE INDEX ix_item_type  ON item_master(item_type);

-- ล็อตการผลิต FG: 1 แถว = 1 Lot ของสินค้า 1 รายการ
CREATE TABLE fg_lot (
  lot_id        INTEGER PRIMARY KEY,
  item_code     VARCHAR(30) NOT NULL REFERENCES item_master(item_code),
  lot_no        VARCHAR(30) NOT NULL,      -- เลข Lot ที่พิมพ์บนบรรจุภัณฑ์ (คอลัมน์ LOT. ต้นฉบับ) หรือเลขภายในถ้าไม่มี
  ana_no        VARCHAR(30),               -- เลขรับเข้า/วิเคราะห์ภายใน เช่น F2609001 (คอลัมน์ ANA.No.)
  prod_doc_no   VARCHAR(30),               -- ใบรับ/ใบผลิต เช่น PFG2609001
  received_date DATE,                      -- วันที่รับเข้าคลังครั้งแรก
  mfg_date      DATE,                      -- วันผลิต (ว่าง = ใช้ received_date)
  exp_date      DATE,                      -- วันหมดอายุ (ว่าง = คำนวณจาก shelf_life_months)
  qc_status     VARCHAR(10) NOT NULL DEFAULT 'RELEASED' CHECK (qc_status IN ('PENDING','RELEASED','HOLD','REJECTED')),
  source        VARCHAR(10) NOT NULL DEFAULT 'NEW'      CHECK (source IN ('IMPORTED','NEW')),
  remark        VARCHAR(300),
  UNIQUE (item_code, lot_no)
);
CREATE INDEX ix_lot_item ON fg_lot(item_code);

CREATE TABLE movement (
  move_id   INTEGER PRIMARY KEY,
  src       VARCHAR(2)  NOT NULL,          -- PK / RM / FG (ไฟล์ต้นทาง)
  move_date DATE,
  doc_no    VARCHAR(50),
  item_code VARCHAR(30) NOT NULL REFERENCES item_master(item_code),
  lot_id    INTEGER REFERENCES fg_lot(lot_id),   -- เฉพาะ FG; NULL = ยังไม่ระบุ Lot (ข้อมูลเก่า)
  move_type VARCHAR(3)  NOT NULL CHECK (move_type IN ('IN','OUT')),
  qty       DECIMAL(16,4) NOT NULL,        -- เก็บค่าเดิมตามต้นฉบับ (บางแถวติดลบ = ปรับยอด)
  remark    VARCHAR(300)
);
CREATE INDEX ix_mov_item ON movement(item_code, move_type);
CREATE INDEX ix_mov_date ON movement(move_date);
CREATE INDEX ix_mov_lot  ON movement(lot_id);

-- สูตรการผลิต: RM (kg ต่อ batch) และ PK (ชิ้นต่อ FG 1 หน่วย)
CREATE TABLE bom (
  bom_id         INTEGER PRIMARY KEY,
  group_id       VARCHAR(10) NOT NULL REFERENCES product_group(group_id),
  formula_name   VARCHAR(200) NOT NULL,    -- ชื่อสูตร/ชื่อ FG ตามต้นฉบับ
  component_code VARCHAR(30) NOT NULL,
  component_type VARCHAR(2)  NOT NULL CHECK (component_type IN ('RM','PK')),
  qty_per_unit   DECIMAL(16,6) NOT NULL,
  basis          VARCHAR(10) NOT NULL CHECK (basis IN ('per_batch','per_FG')),
  qty_verified   INTEGER NOT NULL DEFAULT 0  -- 0 = ค่าตั้งต้น (PK = 1 ชิ้น/FG) ต้องยืนยัน, 1 = มาจากสูตรต้นฉบับ
);
CREATE INDEX ix_bom_group ON bom(group_id);
CREATE INDEX ix_bom_comp  ON bom(component_code);

CREATE TABLE data_issue_log (
  issue_id   INTEGER PRIMARY KEY,
  severity   VARCHAR(5),                   -- INFO / WARN
  table_name VARCHAR(30),
  item_key   VARCHAR(50),
  issue      VARCHAR(300),
  detail     VARCHAR(500)
);


