-- ============ 8) VIEWS ============
-- ยอดคงเหลือ = รวมรับเข้า - รวมจ่ายออก (ตรวจแล้วตรงกับคอลัมน์ Inbound/Outbound ของ Excel)
CREATE VIEW v_stock AS
SELECT i.item_code,
       COALESCE(SUM(CASE WHEN m.move_type='IN'  THEN m.qty END),0) AS in_qty,
       COALESCE(SUM(CASE WHEN m.move_type='OUT' THEN m.qty END),0) AS out_qty,
       COALESCE(SUM(CASE WHEN m.move_type='IN'  THEN m.qty END),0)
     - COALESCE(SUM(CASE WHEN m.move_type='OUT' THEN m.qty END),0) AS on_hand
FROM item_master i LEFT JOIN movement m ON m.item_code = i.item_code
GROUP BY i.item_code;

-- การใช้ย้อนหลัง 90 วัน (นับจากวันที่ล่าสุดที่มีใน movement)
CREATE VIEW v_usage AS
SELECT i.item_code,
       COALESCE(SUM(CASE WHEN m.move_type='OUT' AND m.move_date > date((SELECT MAX(move_date) FROM movement),'-90 day')
                         THEN m.qty END),0) AS out_90d,
       COALESCE(SUM(CASE WHEN m.move_type='OUT' AND m.move_date > date((SELECT MAX(move_date) FROM movement),'-90 day')
                         THEN m.qty END),0) / 90.0 AS avg_daily_out
FROM item_master i LEFT JOIN movement m ON m.item_code = i.item_code
GROUP BY i.item_code;

-- ข้อ 4: ค่า Min/Safe ที่แนะนำ = ใช้เฉลี่ยต่อวัน x (lead time) และ x (lead time + safety)
CREATE VIEW v_reorder_suggestion AS
SELECT i.item_code, i.item_name, i.item_type, i.group_id,
       u.avg_daily_out,
       p.lead_time_days, p.safety_days,
       ROUND(u.avg_daily_out * p.lead_time_days, 2)                    AS suggested_min,
       ROUND(u.avg_daily_out * (p.lead_time_days + p.safety_days), 2)  AS suggested_safe,
       i.min_stock  AS manual_min,
       i.safe_stock AS manual_safe
FROM item_master i
JOIN v_usage u ON u.item_code = i.item_code
JOIN param_lead_time p ON p.item_type = i.item_type;

-- หน้า Dashboard หลัก (แทนชีต Inventory)
--  DISCONTINUED = เลิกใช้ ไม่แจ้งเตือน | NO_USAGE = หมดสต็อกและไม่มีการใช้ใน 90 วัน (รอตัดสินใจ ไม่แจ้งเตือน)
--  CRITICAL = ต่ำกว่า Min หรือหมด | LOW = ต่ำกว่า Safe | OK
CREATE VIEW v_inventory AS
SELECT x.*,
  CASE WHEN x.item_status='DISCONTINUED' THEN 'DISCONTINUED'
       WHEN x.on_hand<=0 AND x.out_90d<=0 THEN 'NO_USAGE'
       WHEN x.on_hand<=0 THEN 'CRITICAL'
       WHEN x.eff_min  IS NOT NULL AND x.on_hand < x.eff_min  THEN 'CRITICAL'
       WHEN x.eff_safe IS NOT NULL AND x.on_hand < x.eff_safe THEN 'LOW'
       ELSE 'OK' END AS stock_status
FROM (
  SELECT i.item_code, i.alt_code, i.item_name, i.item_type, i.group_id, g.group_name, g.brand,
         i.unit, i.buyer, i.status AS item_status,
         s.in_qty, s.out_qty, s.on_hand, u.out_90d, u.avg_daily_out,
         COALESCE(i.min_stock,  r.suggested_min)  AS eff_min,
         COALESCE(i.safe_stock, r.suggested_safe) AS eff_safe,
         CASE WHEN u.avg_daily_out>0 THEN ROUND(s.on_hand/u.avg_daily_out,1) END AS coverage_days,
         CASE WHEN i.unit_cost IS NOT NULL THEN ROUND(s.on_hand*i.unit_cost,2) END AS stock_value,
         i.needs_review
  FROM item_master i
  JOIN v_stock s ON s.item_code=i.item_code
  JOIN v_usage u ON u.item_code=i.item_code
  JOIN v_reorder_suggestion r ON r.item_code=i.item_code
  LEFT JOIN product_group g ON g.group_id=i.group_id
) x;

CREATE VIEW v_alerts AS
SELECT * FROM v_inventory WHERE stock_status IN ('CRITICAL','LOW')
ORDER BY CASE stock_status WHEN 'CRITICAL' THEN 0 ELSE 1 END, coverage_days;

-- รายการที่ควรพิจารณาเลิกใช้ (ยังไม่ถูกปิดอัตโนมัติ ให้คนตัดสินใจแล้ว UPDATE item_master SET status='DISCONTINUED')
CREATE VIEW v_discontinue_candidates AS
SELECT item_code, item_name, item_type, group_name, on_hand FROM v_inventory WHERE stock_status='NO_USAGE';

-- สรุปรายกลุ่มสินค้า
CREATE VIEW v_group_summary AS
SELECT g.group_id, g.group_name,
       SUM(CASE WHEN v.item_type='FG' THEN 1 ELSE 0 END) AS fg_items,
       SUM(CASE WHEN v.item_type='PK' THEN 1 ELSE 0 END) AS pk_items,
       SUM(CASE WHEN v.item_type='RM' THEN 1 ELSE 0 END) AS rm_items,
       SUM(CASE WHEN v.stock_status='CRITICAL' THEN 1 ELSE 0 END) AS critical_items,
       SUM(CASE WHEN v.stock_status='LOW' THEN 1 ELSE 0 END)      AS low_items,
       ROUND(SUM(COALESCE(v.stock_value,0)),2) AS stock_value
FROM product_group g LEFT JOIN v_inventory v ON v.group_id=g.group_id
GROUP BY g.group_id, g.group_name;

-- ผลิตได้อีกกี่ batch (RM) / กี่ชิ้น (PK) ต่อสูตร  -> ตัวที่ทำให้ติดคือ limiting_item
-- short_components = จำนวนส่วนประกอบที่สต็อกหมด (<=0)
CREATE VIEW v_formula_capacity AS
WITH need AS (
  SELECT group_id, formula_name, component_code, component_type, basis,
         SUM(qty_per_unit) AS qty, MIN(qty_verified) AS qty_verified
  FROM bom GROUP BY group_id, formula_name, component_code, component_type, basis
), cap AS (
  SELECT n.*, i.item_name, MAX(s.on_hand,0)*1.0/n.qty AS capacity,
         ROW_NUMBER() OVER (PARTITION BY n.group_id, n.formula_name, n.component_type
                            ORDER BY MAX(s.on_hand,0)*1.0/n.qty, i.item_name) AS rn,
         SUM(CASE WHEN s.on_hand<=0 THEN 1 ELSE 0 END)
             OVER (PARTITION BY n.group_id, n.formula_name, n.component_type) AS short_components
  FROM need n JOIN v_stock s ON s.item_code=n.component_code
              JOIN item_master i ON i.item_code=n.component_code
  WHERE n.qty>0
)
SELECT group_id, formula_name, component_type, basis,
       ROUND(capacity,2) AS max_capacity, item_name AS limiting_item,
       short_components, qty_verified
FROM cap WHERE rn=1;

CREATE VIEW v_bom_unmatched AS
SELECT b.* FROM bom b LEFT JOIN item_master i ON i.item_code=b.component_code WHERE i.item_code IS NULL;


-- ============ 9) LOT FG ============
-- ยอดคงเหลือรายล็อต + วันหมดอายุที่ใช้จริง (exp_date หรือคำนวณจาก mfg/received + shelf_life_months)
CREATE VIEW v_lot_stock AS
SELECT l.lot_id, l.item_code, i.item_name, i.group_id, l.lot_no, l.ana_no, l.prod_doc_no, l.qc_status,
       l.received_date,
       COALESCE(l.exp_date,
         CASE WHEN i.shelf_life_months IS NOT NULL
              THEN date(COALESCE(l.mfg_date,l.received_date), '+' || i.shelf_life_months || ' months') END) AS exp_date_eff,
       COALESCE(SUM(CASE WHEN m.move_type='IN'  THEN m.qty END),0) AS in_qty,
       COALESCE(SUM(CASE WHEN m.move_type='OUT' THEN m.qty END),0) AS out_qty,
       COALESCE(SUM(CASE WHEN m.move_type='IN'  THEN m.qty END),0)
     - COALESCE(SUM(CASE WHEN m.move_type='OUT' THEN m.qty END),0) AS on_hand,
       CAST(julianday('now') - julianday(l.received_date) AS INTEGER) AS age_days
FROM fg_lot l
JOIN item_master i ON i.item_code=l.item_code
LEFT JOIN movement m ON m.lot_id=l.lot_id
GROUP BY l.lot_id;

-- ยอดรวมของ FG เทียบกับยอดที่ระบุ Lot แล้ว (unallocated = ข้อมูลเก่าที่ยังไม่ผูก Lot)
CREATE VIEW v_fg_lot_reconcile AS
SELECT s.item_code, i.item_name, s.on_hand AS total_on_hand,
       COALESCE(l.lot_on_hand,0) AS lot_assigned,
       s.on_hand - COALESCE(l.lot_on_hand,0) AS unallocated,
       CASE WHEN l.lot_on_hand IS NULL THEN 'NO_LOT'
            WHEN s.on_hand - l.lot_on_hand < 0 THEN 'LOT_OVERSTATED'   -- มีการจ่ายออกที่ยังไม่ระบุ Lot ยอดรายล็อตสูงกว่าจริง
            WHEN s.on_hand - l.lot_on_hand = 0 THEN 'FULLY_TRACKED'
            ELSE 'PARTIAL' END AS lot_coverage
FROM v_stock s
JOIN item_master i ON i.item_code=s.item_code AND i.item_type='FG'
LEFT JOIN (SELECT item_code, SUM(on_hand) AS lot_on_hand FROM v_lot_stock GROUP BY item_code) l ON l.item_code=s.item_code;

-- ลำดับการหยิบ (FEFO: หมดอายุก่อนหยิบก่อน, ถ้าไม่มีวันหมดอายุใช้ FIFO ตามวันรับเข้า) เฉพาะ Lot ที่ RELEASED และมียอด
CREATE VIEW v_lot_fefo AS
SELECT item_code, item_name, lot_id, lot_no, received_date, exp_date_eff, on_hand,
       ROW_NUMBER() OVER (PARTITION BY item_code
                          ORDER BY CASE WHEN exp_date_eff IS NULL THEN 1 ELSE 0 END, exp_date_eff, received_date, lot_id) AS pick_order
FROM v_lot_stock
WHERE qc_status='RELEASED' AND on_hand>0;

-- Lot ที่หมดอายุแล้ว หรือใกล้หมดอายุใน 180 วัน (ต้องมี exp_date หรือ shelf_life_months)
CREATE VIEW v_lot_expiry_alerts AS
SELECT item_code, item_name, lot_no, on_hand, exp_date_eff,
       CAST(julianday(exp_date_eff) - julianday('now') AS INTEGER) AS days_to_expiry,
       CASE WHEN exp_date_eff < date('now') THEN 'EXPIRED' ELSE 'NEAR_EXPIRY' END AS expiry_status
FROM v_lot_stock
WHERE on_hand>0 AND exp_date_eff IS NOT NULL AND exp_date_eff <= date('now','+180 day')
ORDER BY exp_date_eff;

-- ============ 10) TRIGGERS (สร้างหลังโหลดข้อมูล เพื่อคุมรายการใหม่) ============
-- Lot ต้องเป็นของสินค้าเดียวกับรายการเคลื่อนไหว
CREATE TRIGGER trg_mov_lot_item BEFORE INSERT ON movement
WHEN NEW.lot_id IS NOT NULL
BEGIN
  SELECT RAISE(ABORT,'lot_id ไม่ตรงกับ item_code')
  WHERE NOT EXISTS (SELECT 1 FROM fg_lot WHERE lot_id=NEW.lot_id AND item_code=NEW.item_code);
END;
-- ห้ามจ่ายออกเกินยอดคงเหลือของ Lot และห้ามจ่ายจาก Lot ที่ไม่ใช่ RELEASED
CREATE TRIGGER trg_mov_lot_overdraw BEFORE INSERT ON movement
WHEN NEW.lot_id IS NOT NULL AND NEW.move_type='OUT'
BEGIN
  SELECT RAISE(ABORT,'Lot นี้ไม่ได้อยู่ในสถานะ RELEASED')
  WHERE (SELECT qc_status FROM fg_lot WHERE lot_id=NEW.lot_id) <> 'RELEASED';
  SELECT RAISE(ABORT,'จ่ายออกเกินยอดคงเหลือของ Lot')
  WHERE NEW.qty > (SELECT COALESCE(SUM(CASE WHEN move_type='IN' THEN qty ELSE -qty END),0) FROM movement WHERE lot_id=NEW.lot_id);
END;

